package dev.kubejseditor.verification;

import com.google.gson.*;
import dev.kubejseditor.client.*;
import dev.kubejseditor.model.EditorProject;
import dev.kubejseditor.recipe.*;
import dev.kubejseditor.recipe.compat.*;
import dev.kubejseditor.runtime.*;
import dev.kubejseditor.storage.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.gui.components.*;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import java.nio.file.*;
import java.util.*;

/** Exactly one launch/session. Tests the framework once, without named-machine editing fixtures. */
@EventBusSubscriber(modid="kubejs_editor_verification",value=Dist.CLIENT)
public final class ClientCompat015Verification {
    private static final String ID="kubejs_editor_verification:framework";
    private static int phase,ticks,checks;private static EditorRuntime.ReloadResult result;private static CompatibilityScreen screen;private static final JsonObject report=new JsonObject();private static final JsonArray notes=new JsonArray();
    private static Path root(){return Minecraft.getInstance().gameDirectory.toPath();}
    private static void check(boolean ok,String message){checks++;notes.add(message);if(!ok)throw new AssertionError(message);}
    private static Object field(Object object,String name)throws Exception{for(Class<?> c=object.getClass();c!=null;c=c.getSuperclass())try{var f=c.getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    private static Object call(Object object,String name,Class<?>[] types,Object...args)throws Exception{var m=object.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(object,args);}
    private static void click(String label){var mc=Minecraft.getInstance();var current=mc.screen;var button=current.children().stream().filter(c->c instanceof Button b&&b.getMessage().getString().equals(label)).map(c->(Button)c).findFirst().orElseThrow(()->new AssertionError("No button "+label));check(button.active,"Button enabled "+label);current.mouseClicked(button.getX()+2,button.getY()+2,0);current.mouseReleased(button.getX()+2,button.getY()+2,0);}
    private static RecipePresentation p()throws Exception{return (RecipePresentation)field(screen,"presentation");}
    private static RecipePresentation.Binding binding(String path)throws Exception{return p().bindings().stream().filter(b->b.path().equals(path)).findFirst().orElseThrow(()->new AssertionError("Missing binding "+path));}
    @SuppressWarnings("unchecked") private static List<CompatJeiLayouts.BoundRegion> regions()throws Exception{return (List<CompatJeiLayouts.BoundRegion>)field(screen,"regions");}
    private static void show()throws Exception{CompatibilityScreenOpen.open(new WorkspaceScreen(),ID);check(Minecraft.getInstance().screen instanceof CompatibilityScreen,"Shared native workbench opens");screen=(CompatibilityScreen)Minecraft.getInstance().screen;}
    private static void prepare()throws Exception{var mc=Minecraft.getInstance();EditorRuntime.project();SimpleRecipes.setEnabled(EditorRuntime.root(),true);EditorRuntime.invalidateRecipes();show();check(p().definition.source.equals("jei-native"),"Unrecognized serializer automatically relates JSON to JEI, without dedicated adapter");check(binding("/feedstock").field().quantity.equals("count"),"Nested quantity is discovered");check(p().item(binding("/feedstock")).get("count").getAsInt()==20480,"20480 is an independent native quantity");check(!CompatIngredients.binding(p(),binding("/feedstock")).isEmpty(),"Large ingredient has a legal display fingerprint");check(binding("/bath").fluid(),"Nested fluid automatically recognized");check(binding("/extra").field().kind==CompatDefinition.Kind.OTHER,"Registered third-party ingredient codec automatically recognized");check(regions().size()==4,"Four logical slots auto-bind, including unnamed slots");check(CompatLabels.name(binding("/settings/work").field()).codePoints().anyMatch(c->c>=0x3400&&c<=0x9fff),"Unknown field has Chinese role label plus original name");
        click("字段映射");var mapping=Minecraft.getInstance().screen;String initial=ProjectStore.JSON.toJson(field(mapping,"definition"));check(!(boolean)field(mapping,"advanced"),"Field confirmation starts in basic mode");click("模式：初级");check((boolean)field(mapping,"advanced"),"Advanced mode opens existing detailed mapping");click("模式：高级");check(initial.equals(ProjectStore.JSON.toJson(field(mapping,"definition"))),"Mode switching preserves definition and advanced semantics");mc.screen.onClose();
        var view=(CompatJeiLayouts.View)field(screen,"view");var first=view.slots().stream().filter(s->s.role()==mezz.jei.api.recipe.RecipeIngredientRole.INPUT&&s.item()).findFirst().orElseThrow();CompatJeiLayouts.mark(ID,view,screen.draft.data,binding("/feedstock").key(),first.rect());CompatJeiLayouts.mark(ID,view,screen.draft.data,binding("/feedstock").key(),new net.minecraft.client.renderer.Rect2i(4,58,16,16));show();check(regions().stream().filter(r->r.binding().equals("/feedstock@0")).count()==2,"One native ingredient binds multiple independent positions");
        var item=WorkspaceJeiPlugin.runtime.getIngredientManager().createTypedIngredient(new ItemStack(Items.COPPER_INGOT)).orElseThrow();var target=regions().stream().filter(r->r.binding().equals("/feedstock@0")).toList().getLast();var rect=(net.minecraft.client.renderer.Rect2i)call(screen,"screenRect",new Class[]{net.minecraft.client.renderer.Rect2i.class},target.rect());WorkspaceJeiPlugin.compatibilityGhostHandler().getTargetsTyped(screen,item,true).stream().filter(t->CompatJeiLayouts.sameRect(t.getArea(),rect)).findFirst().orElseThrow().accept(item.getIngredient());check(p().item(binding("/feedstock")).get("count").getAsInt()==20480,"Editing an alias does not multiply or clamp quantity");check(p().item(binding("/feedstock")).get("item").getAsString().equals("minecraft:copper_ingot"),"Alias drop edits the shared native ingredient");
        call(screen,"edit",new Class[]{RecipePresentation.Binding.class},binding("/feedstock"));click("任意一种（OR）");check(mc.screen instanceof CompatAlternativesScreen,"Basic OR editor opens");click("+ 添加候选");((EditBox)field(mc.screen,"identity")).setValue("#c:ingots/iron");click("保存");click("保存");check(p().item(binding("/feedstock")).getAsJsonArray("alternatives").size()==2,"OR adds a tag alternative without creating two consuming slots");check(screen.draft.data.getAsJsonObject("feedstock").get("count").getAsInt()==20480,"OR preserves sized native wrapper");
        var token=new GenericCompatFixture.Token(ResourceLocation.fromNamespaceAndPath(GenericCompatFixture.MOD,"blue"),7);var typed=WorkspaceJeiPlugin.runtime.getIngredientManager().createTypedIngredient(GenericCompatFixture.TOKEN,token).orElseThrow();var other=regions().stream().filter(r->r.binding().equals("/extra@0")).findFirst().orElseThrow();var area=(net.minecraft.client.renderer.Rect2i)call(screen,"screenRect",new Class[]{net.minecraft.client.renderer.Rect2i.class},other.rect());WorkspaceJeiPlugin.compatibilityGhostHandler().getTargetsTyped(screen,typed,true).stream().filter(t->CompatJeiLayouts.sameRect(t.getArea(),area)).findFirst().orElseThrow().accept(token);check(screen.draft.data.getAsJsonObject("extra").get("quantity").getAsInt()==7,"Other ingredient drop uses registered native codec");
        call(screen,"edit",new Class[]{RecipePresentation.Binding.class},binding("/settings/work"));((MultiLineEditBox)field(mc.screen,"input")).setValue("80");click("检查并保存");call(screen,"edit",new Class[]{RecipePresentation.Binding.class},binding("/settings/enabled"));check(!screen.draft.data.getAsJsonObject("settings").get("enabled").getAsBoolean(),"Existing condition can be changed in basic controls");var saved=ProjectStore.read(EditorRuntime.root()).recipes.get(ID);check(saved!=null&&saved.compatibility!=null,"Schema-2 draft persists generic binding metadata");show();check(p().item(binding("/feedstock")).getAsJsonArray("alternatives").size()==2,"Reopening retains OR, wrappers and metadata");EditorRuntime.validateRecipe(screen.draft.data,Set.of());check(EditorRuntime.validationIssues().isEmpty(),"Whole proposed document passes native codec checks");report.add("draft",screen.draft.data.deepCopy());mc.options.guiScale().set(2);mc.resizeDisplay();}
    private static GenericCompatFixture.GenericRecipe nativeRecipe(){return (GenericCompatFixture.GenericRecipe)Minecraft.getInstance().getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse(ID)).orElseThrow().value();}
    private static void finish(Throwable error)throws Exception{report.addProperty("passed",error==null);report.addProperty("checks",checks);report.addProperty("gameLaunches",1);report.addProperty("phase",phase);report.add("checksDetail",notes);if(error!=null){var writer=new java.io.StringWriter();error.printStackTrace(new java.io.PrintWriter(writer));report.addProperty("error",writer.toString());}Files.writeString(root().resolve("compat015-verification.json"),ProjectStore.JSON.toJson(report));phase=99;Minecraft.getInstance().stop();}
    @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!Boolean.getBoolean("kubejs.editor.verifyCompat015")||phase==99)return;var mc=Minecraft.getInstance();ticks++;try{if(ticks>7200)throw new AssertionError("Timeout "+phase+" "+EditorRuntime.activationError);
        if(phase==0&&mc.screen instanceof TitleScreen&&ticks>80){check(!Files.exists(root().resolve("compat015-verification.json")),"Single fresh validation session");mc.createWorldOpenFlows().openWorld("EditorVerification",()->{});phase=1;ticks=0;return;}
        if(phase==1&&mc.level!=null&&mc.player!=null&&WorkspaceJeiPlugin.runtime!=null&&ticks>160){prepare();phase=2;ticks=0;return;}
        if(phase==2&&ticks>20){Screenshot.grab(mc.gameDirectory,"compat015-scale2.png",mc.getMainRenderTarget(),c->{});mc.options.guiScale().set(3);mc.resizeDisplay();phase=3;ticks=0;return;}
        if(phase==3&&ticks>20){check(!screen.dropTargets(new ItemStack(Items.DIAMOND)).isEmpty(),"GUI scale 3 keeps typed drag targets");Screenshot.grab(mc.gameDirectory,"compat015-scale3.png",mc.getMainRenderTarget(),c->{});var review=EditorRuntime.review();EditorRuntime.apply(review);result=null;EditorRuntime.reloadResult(false,r->result=r);phase=4;ticks=0;return;}
        if(phase==4&&result!=null){check(result.success(),"Edited native recipe applies and loads: "+result.message());check(nativeRecipe().feedstock().count()==20480&&nativeRecipe().settings().work()==80&&nativeRecipe().extra().quantity()==7,"Actual loaded recipe retains all generic edits");check(nativeRecipe().feedstock().ingredient().test(new ItemStack(Items.COPPER_INGOT))&&nativeRecipe().feedstock().ingredient().test(new ItemStack(Items.IRON_INGOT)),"Actual loaded OR accepts either candidate");var pending=new EditorProject.RecipeDraft("kubejs_editor_verification:pending",RecipeAdapters.parse("{type:'minecraft:crafting_shapeless',ingredients:[{item:'minecraft:stick'}],result:{id:'minecraft:paper'}}"));EditorRuntime.project().recipes.put(pending.id,pending);EditorRuntime.saveDraft();result=null;EditorRuntime.revokeRecipe(ID,r->result=r);phase=5;ticks=0;return;}
        if(phase==5&&result!=null){check(result.success(),"Revoke succeeds in same session");check(nativeRecipe().settings().work()==40&&nativeRecipe().extra().quantity()==4,"Revoke restores authoritative source");check(EditorRuntime.project().recipes.containsKey("kubejs_editor_verification:pending"),"Revoke retains unrelated pending work");check(!Files.exists(root().resolve(WorkspaceState.GENERATED.getFirst())),"Last rule cleanup removes generated script");EditorRuntime.rollback();result=null;EditorRuntime.reloadResult(false,r->result=r);phase=6;ticks=0;return;}
        if(phase==6&&result!=null){check(result.success()&&nativeRecipe().settings().work()==80,"Rollback restores generated rule and native content");finish(null);}
    }catch(Throwable e){e.printStackTrace();try{finish(e);}catch(Exception write){write.printStackTrace();phase=99;mc.stop();}}}
    private ClientCompat015Verification(){}
}
